import torch


def run_correctness(x):
    x.copy_(torch.asin(x.float()).to(x.dtype))
    return x


def run(x):
    return torch.asin_(x)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref = ref_outputs[0].detach().to("cpu")
    sol = sol_outputs[0].detach().to("cpu")
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}"}
    dtype = sol.dtype
    rtol_map = {
        torch.float16: 1e-3,
        torch.bfloat16: 1.6e-2,
        torch.float32: 1.3e-6,
    }
    rtol = rtol_map.get(dtype, 1.3e-6)
    atol = 1e-4
    ref64 = ref.to(torch.float64)
    sol64 = sol.to(torch.float64)
    both_nan = torch.isnan(ref64) & torch.isnan(sol64)
    both_posinf = torch.isposinf(ref64) & torch.isposinf(sol64)
    both_neginf = torch.isneginf(ref64) & torch.isneginf(sol64)
    finite = torch.isfinite(ref64) & torch.isfinite(sol64)
    close = torch.zeros_like(ref64, dtype=torch.bool)
    close[finite] = (ref64[finite] - sol64[finite]).abs() <= atol + rtol * ref64[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
